#!/usr/bin/env bash
#
# Creates an annotated release tag, with the release notes generated by git-cliff as its message.
# See RELEASING.md.

set -euo pipefail

if ! command -v git-cliff > /dev/null; then
    echo "git-cliff is not installed, see https://git-cliff.org" >&2
    exit 1
fi

branch="$(git rev-parse --abbrev-ref HEAD)"
if [[ "${branch}" != "main" ]]; then
    echo "Releases are tagged on 'main', but the current branch is '${branch}'." >&2
    exit 1
fi

tag="$(git cliff --bumped-version --unreleased --use-branch-tags)"
message="$(git cliff --bump --unreleased --use-branch-tags)"

if git rev-parse --quiet --verify "refs/tags/${tag}" > /dev/null; then
    echo "Tag '${tag}' already exists, there are probably no releasable changes since the previous tag." >&2
    exit 1
fi

echo "Tag: ${tag}"
echo
echo "${message}"
echo

read -r -p "Create this tag? [y/N] " answer
if [[ ! "${answer}" =~ ^[Yy]$ ]]; then
    echo "Aborted, no tag was created."
    exit 1
fi

# --cleanup=verbatim keeps the markdown headings (lines starting with '#') in the tag message.
git tag -a "${tag}" -m "${message}" --cleanup=verbatim

echo
git show --no-patch "${tag}"
echo
echo "Check the tag above, then push it with: git push origin ${tag}"
